  'chat.workStatus.telemetry.responseSpeed': 'Ответ',
  'chat.workStatus.telemetry.responseSpeedDescription': 'Как быстро пришёл итоговый текст. Без первоначального ожидания, размышлений и предыдущих вызовов инструментов. Оценка по меткам времени текста, а не измерение скорости провайдера.',
  'chat.workStatus.telemetry.speed': 'Весь ход',
  'chat.workStatus.telemetry.speedDescription': 'Токены, сгенерированные по всем шагам, включая размышления, делённые на время без выполнения инструментов. Ожидание модели тоже учитывается, поэтому много коротких вызовов инструментов может занизить это число.',
  'chat.workStatus.telemetry.elapsed': 'Прошло',
  'chat.workStatus.telemetry.elapsedDescription': 'Астрономическое время от первого сообщения пользователя до последнего ответа ассистента. Включает ожидание модели, выполнение инструментов, сжатие и другие паузы.',
  'chat.workStatus.telemetry.llmDuration': 'Время модели',
  'chat.workStatus.telemetry.llmDurationDescription': 'Время, затраченное на все шаги модели, включая ожидание ответов. Время выполнения инструментов исключено. Это не только время генерации текста.',
  'chat.workStatus.telemetry.toolDuration': 'Инструменты',
  'chat.workStatus.telemetry.toolDurationDescription': 'Время выполнения инструментов, включая неудачные вызовы. Одновременно работающие инструменты считаются один раз, а не складываются.',
  'chat.workStatus.telemetry.ttft': 'Средний TTFT',
  'chat.workStatus.telemetry.ttftDescription': 'Среднее ожидание до начала первого текста или размышлений в каждом шаге модели. Скрывается, когда у шага нет старта после создания — это обычно для шагов только с инструментами и для частей с меткой времени создания.',
  'chat.workStatus.telemetry.steps': 'Шаги',
  'chat.workStatus.telemetry.stepsDescription': 'Сколько раз модель вызывалась для этого промпта. Чтение результатов инструментов и решение, что делать дальше, обычно занимают ещё один шаг.',
  'chat.workStatus.telemetry.tokens': 'Токены',
  'chat.workStatus.telemetry.tokens.inOut': '{input} ↑ · {output} ↓',
  'chat.workStatus.telemetry.tokensDescription': '↑ Ввод без кэшированных токенов: {input}. ↓ Сгенерированные токены: {output} для текста и вызовов инструментов, плюс {reasoning} для размышлений. Итоги охватывают все шаги этого промпта.',
  'chat.workStatus.telemetry.cacheHit': 'Кэш',
  'chat.workStatus.telemetry.cacheHitDescription': 'Доля вводных токенов, повторно использованных из кэша промпта по всем шагам. Повторное использование контекста может снизить расходы и ожидание, но это не оценка скорости.',
  'chat.workStatus.telemetry.cost': 'Стоимость',
  'chat.workStatus.telemetry.costDescription': 'Стоимость от провайдера для всех шагов модели этого промпта, в долларах США. Без отдельных сессий субагентов. Ноль может означать бесплатную модель или провайдера, не сообщающего стоимость.',
